import re

def has_invoice_number(output):
    return re.match(r"#\d{4}", output) is not None

def format_errors(err):
    lines = []
    for e in err.errors():
        where = ".".join(str(p) for p in e["loc"]) or "(root)"
        lines.append(f"{where}: {e['msg']}")
    return "\n".join(lines)

def norm(s):
